/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,12],[12,26],[26,44],[44,62],[62,80]]);
  v.uO = lin([[0,0],[4,1]]) * out;
  v.hlO = lin([[2,0],[5,1],[10,1],[13,0]]);
  v.ruleO = lin([[12,0],[15,1]]) * out; v.ruleT = 'translateY(' + lin([[12,14],[15,0]]).toFixed(1) + 'px)';
  v.fillO = lin([[26,0],[34,1]]) * out; v.nameO = lin([[30,0],[38,1]]) * out;
  var wd = lin([[44,0],[54,1]]);
  v.wall = 'stroke-dasharray: 1; stroke-dashoffset: ' + (1 - wd).toFixed(3) + '; opacity: ' + ((wd > 0.002 ? 1 : 0) * out) + ';';
  v.doorO = lin([[53,0],[59,1]]) * out;
  v.areaO = lin([[62,0],[68,1]]) * out;
  for (var i = 0; i < 5; i++) v['k'+i] = (p >= 64 + i * 2 && p < 97) ? out : 0;
  v.fin = (p >= 76 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
